'use strict';
const crypto = require('crypto');
const EventEmitter = require('events');

class SessionStore {
  constructor() {
    this.sessions = Object.create(null);
  }

  createSession(userId, roles) {
    const sid = crypto.randomBytes(32).toString('hex');
    this.sessions[sid] = { userId, roles, createdAt: Date.now() };
    return sid;
  }

  getSession(sid) {
    return this.sessions[sid] || null;
  }
}

class ResourceRegistry {
  constructor() {
    // Registry mapping resource paths to required role
    this.acl = {};
  }

  registerResource(path, requiredRole) {
    if (typeof path !== 'string' || typeof requiredRole !== 'string') {
      throw new Error('Invalid registration parameters');
    }
    this.acl[path] = requiredRole;
  }

  getRequiredRole(path) {
    return this.acl[path] || null;
  }
}

class AuthorizationEngine extends EventEmitter {
  constructor(sessionStore, resourceRegistry) {
    super();
    this.sessionStore = sessionStore;
    this.resourceRegistry = resourceRegistry;
    this.auditLog = [];
  }

  normalizeResourcePath(rawPath) {
    // Normalize path: lowercase, trim whitespace, remove trailing slash
    let normalized = rawPath.trim().toLowerCase();
    if (normalized.length > 1 && normalized.endsWith('/')) {
      normalized = normalized.slice(0, -1);
    }
    // Collapse double slashes
    normalized = normalized.replace(/\/\//g, '/');
    return normalized;
  }

  checkAuthorization(sessionId, rawResourcePath) {
    const session = this.sessionStore.getSession(sessionId);
    if (!session) {
      this.emit('auth_failure', { reason: 'invalid_session', path: rawResourcePath });
      return { authorized: false, reason: 'invalid_session' };
    }

    const resourcePath = this.normalizeResourcePath(rawResourcePath);
    const requiredRole = this.resourceRegistry.getRequiredRole(resourcePath);

    if (requiredRole === null) {
      // Resource not registered - deny by default
      this.auditLog.push({ userId: session.userId, path: resourcePath, result: 'denied_unregistered' });
      return { authorized: false, reason: 'resource_not_registered' };
    }

    // Check if user has the required role
    const hasRole = session.roles.includes(requiredRole);

    if (hasRole) {
      this.auditLog.push({ userId: session.userId, path: resourcePath, result: 'granted' });
      return { authorized: true };
    }

    this.emit('auth_failure', { reason: 'insufficient_role', userId: session.userId, path: resourcePath });
    this.auditLog.push({ userId: session.userId, path: resourcePath, result: 'denied_role' });
    return { authorized: false, reason: 'insufficient_role' };
  }
}

class RequestHandler {
  constructor() {
    this.sessionStore = new SessionStore();
    this.resourceRegistry = new ResourceRegistry();
    this.authEngine = new AuthorizationEngine(this.sessionStore, this.resourceRegistry);
    this.setupResources();
  }

  setupResources() {
    this.resourceRegistry.registerResource('/api/public/health', 'viewer');
    this.resourceRegistry.registerResource('/api/admin/users', 'admin');
    this.resourceRegistry.registerResource('/api/admin/config', 'admin');
    this.resourceRegistry.registerResource('/api/data/reports', 'analyst');
    this.resourceRegistry.registerResource('/api/data/export', 'analyst');
  }

  handleLogin(userId, password) {
    // Simplified auth - in production would verify against secure store
    const userDb = {
      'alice': { password: 'hashed_pw_alice', roles: ['admin', 'analyst', 'viewer'] },
      'bob': { password: 'hashed_pw_bob', roles: ['analyst', 'viewer'] },
      'charlie': { password: 'hashed_pw_charlie', roles: ['viewer'] }
    };

    const user = userDb[userId];
    if (!user || user.password !== password) {
      return { success: false };
    }

    const sessionId = this.sessionStore.createSession(userId, user.roles);
    return { success: true, sessionId };
  }

  handleRequest(sessionId, method, path, body) {
    const authResult = this.authEngine.checkAuthorization(sessionId, path);

    if (!authResult.authorized) {
      return { status: 403, body: { error: authResult.reason } };
    }

    // Process the authorized request
    return this.processAuthorizedRequest(method, path, body);
  }

  processAuthorizedRequest(method, path, body) {
    if (method === 'GET') {
      return { status: 200, body: { data: `Response for ${path}` } };
    }
    if (method === 'POST' && body) {
      // Process body - merge with defaults
      const defaults = {};
      const merged = this.mergeConfig(defaults, body);
      return { status: 200, body: { data: merged } };
    }
    return { status: 405, body: { error: 'method_not_allowed' } };
  }

  mergeConfig(target, source) {
    for (const key of Object.keys(source)) {
      if (typeof source[key] === 'object' && source[key] !== null && !Array.isArray(source[key])) {
        target[key] = target[key] || {};
        this.mergeConfig(target[key], source[key]);
      } else {
        target[key] = source[key];
      }
    }
    return target;
  }
}

module.exports = { RequestHandler, SessionStore, ResourceRegistry, AuthorizationEngine };
